    /**
     * Method to retrieve the Authorization via AuthorizationFetchOneSummary
     * @param 	summary AuthorizationFetchOneSummary 
     * @return 	AuthorizationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Authorization getAuthorization( AuthorizationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AuthorizationFetchOneSummary arg cannot be null" );
    	
    	Authorization entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Authorization
        	// --------------------------------------
        	CompletableFuture<Authorization> futureEntity = queryGateway.query(new FindAuthorizationQuery( new LoadAuthorizationFilter( summary.getAuthorizationId() ) ), ResponseTypes.instanceOf(Authorization.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Authorization with id " + summary.getAuthorizationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


