    /**
     * assign Coverage on Authorization
     * @param		command AssignCoverageToAuthorizationCommand	
     * @exception	ProcessingException
     */     
	public void assignCoverage( AssignCoverageToAuthorizationCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getAuthorizationId() );
		
		CoverageService childDelegate 	= CoverageService.getCoverageInstance();
		AuthorizationService parentDelegate = AuthorizationService.getAuthorizationInstance();			
		UUID childId = command.getAssignment().getCoverageId();
		Coverage child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Coverage using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

